using System.ComponentModel;using System.Runtime.CompilerServices;using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.IO;
namespace AulaControlTeacher;
public class Device:INotifyPropertyChanged{string dn="",user="",course="",model="",ip="",android="";int bat=-1;bool screen;DateTime seen;public string Id{get;set;}="";public string DeviceName{get=>dn;set=>Set(ref dn,value);}public string User{get=>user;set=>Set(ref user,value);}public string Course{get=>course;set=>Set(ref course,value);}public string Model{get=>model;set=>Set(ref model,value);}public string Ip{get=>ip;set=>Set(ref ip,value);}public string Android{get=>android;set=>Set(ref android,value);}public int CommandPort{get;set;}=45901;public int ScreenPort{get;set;}=45902;public int Battery{get=>bat;set=>Set(ref bat,value);}public bool Screen{get=>screen;set=>Set(ref screen,value);}public DateTime Seen{get=>seen;set{Set(ref seen,value);On(nameof(Status));On(nameof(SeenText));}}public string Name=>string.IsNullOrWhiteSpace(DeviceName)?Id:DeviceName;public string Person=>string.IsNullOrWhiteSpace(User)?"Sin sesión":User;public string CourseText=>string.IsNullOrWhiteSpace(Course)?"—":Course;public string Status=>DateTime.Now-Seen<TimeSpan.FromSeconds(9)?"● En línea":"○ Sin conexión";public string SeenText=>Seen==default?"—":Seen.ToString("HH:mm:ss");public event PropertyChangedEventHandler? PropertyChanged;public void Computed(){On(nameof(Status));On(nameof(SeenText));}public void Identity(){On(nameof(Name));On(nameof(Person));On(nameof(CourseText));}void Set<T>(ref T f,T v,[CallerMemberName]string? n=null){if(Equals(f,v))return;f=v;On(n);if(n==nameof(DeviceName))On(nameof(Name));if(n==nameof(User))On(nameof(Person));if(n==nameof(Course))On(nameof(CourseText));}void On(string? n)=>PropertyChanged?.Invoke(this,new(n));}
public static class AcCrypto{public static string Sha(string s)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s))).ToLowerInvariant();public static string Hmac(string k,string d){using var h=new HMACSHA256(Encoding.UTF8.GetBytes(k));return Convert.ToHexString(h.ComputeHash(Encoding.UTF8.GetBytes(d))).ToLowerInvariant();}}
public class Settings{public string Key{get;set;}="";static string Dir=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AulaControl");static string File=>Path.Combine(Dir,"settings.json");public static Settings Load(){try{return System.IO.File.Exists(File)?JsonSerializer.Deserialize<Settings>(System.IO.File.ReadAllText(File))??new():new();}catch{return new();}}public void Save(){Directory.CreateDirectory(Dir);System.IO.File.WriteAllText(File,JsonSerializer.Serialize(this));}}
public class Registry{readonly string file;public Registry(string key){var d=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AulaControl");Directory.CreateDirectory(d);file=Path.Combine(d,"devices-"+AcCrypto.Sha(key)[..12]+".json");}public List<Device> Load(){try{return System.IO.File.Exists(file)?JsonSerializer.Deserialize<List<Device>>(System.IO.File.ReadAllText(file))??new():new();}catch{return new();}}public void Save(IEnumerable<Device> d){try{System.IO.File.WriteAllText(file,JsonSerializer.Serialize(d));}catch{}}}
public static class SessionLog{static readonly object Gate=new();static string File{get{var d=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AulaControl");Directory.CreateDirectory(d);return Path.Combine(d,"session-history.csv");}}public static void Change(string id,string oldU,string newU,string course){lock(Gate){if(!System.IO.File.Exists(File))System.IO.File.WriteAllText(File,"timestamp,device_id,previous_user,new_user,course\r\n",Encoding.UTF8);System.IO.File.AppendAllText(File,$"{Csv(DateTime.Now.ToString("s"))},{Csv(id)},{Csv(oldU)},{Csv(newU)},{Csv(course)}\r\n",Encoding.UTF8);}}static string Csv(string s)=>"\""+(s??"").Replace("\"","\"\"")+"\"";}
